function UIFishPoolChooseFishingCouponPopupDialog:__init() 
    self._fishPlaceId = 0                --渔场id
    self._activityId = 0                 --活动id
end

function UIFishPoolChooseFishingCouponPopupDialog:__delete()
    self._fishPlaceId = nil                --渔场id
    self._activityId = nil                 --活动id
end

function UIFishPoolChooseFishingCouponPopupDialog:Awake()
    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end
    self._fishPlaceId = checkNumber(argument.fishPlaceId)    
    self._isFirst = checkNumber(argument.isFirst) 

    self._activityId = FishingUtils.GetFishPlaceActivityId(self._fishPlaceId, ConstantsFishing.ActivityType.Summer)
    if self._activityId == 0 then
        return
    end

    self:FillSelf()
end

function UIFishPoolChooseFishingCouponPopupDialog:FillSelf()
    local scr = CfUtils.GetLuaScr(self.GroupL, UIFishPoolChooseFishingCouponPopupNode)
    if scr then
        scr:Refresh(Constants.Currency.FishConsume, function()
            self:OnSelect(Constants.Currency.FishConsume, ConstantsFishing.ActivityType.Common)
        end)
    end

    scr = CfUtils.GetLuaScr(self.GroupR, UIFishPoolChooseFishingCouponPopupNode)
    if scr then
        local goodsId = FishingUtils.GetActivityCurrencyId(self._activityId)
        scr:Refresh(goodsId, function()
            self:OnSelect(goodsId, ConstantsFishing.ActivityType.Summer)
        end, self._isFirst)
    end
end

function UIFishPoolChooseFishingCouponPopupDialog:OnSelect(goodsId, type)
    if checkNumber(goodsId) < 1 then
        return
    end
    local curId = FishingUtils.GetCurUseCurrency(self._fishPlaceId, ConstantsFishing.ActivityType.Summer)
    if checkNumber(goodsId) == checkNumber(curId) then
        Events.Broadcast(Constants.EventNames.FishActivityCurrencyChange, nil)
        UIModule.CloseDialog(self.controller)
        return
    end

    fishingComponent:FishingSwitchTicketReq(self._fishPlaceId, type, function()
        Events.Broadcast(Constants.EventNames.FishActivityCurrencyChange, nil)
        UIModule.CloseDialog(self.controller)
    end)
end

